task.vi:
Chỉ ra kết quả xuất ra màn hình của đoạn mã sau với giá trị nhập vào là 120:
```cpp
#include <iostream>
using namespace std;

int main()
{
  cout << "Enter a temperature: ";
  double temperature;
  cin >> temperature;

  try
  {
    cout << "Start of try block ..." << endl;
    if (temperature > 95)
      throw temperature;
    cout << "End of try block ..." << endl;
  }
  catch (double temperature)
  {
    cout << "The temperature is " << temperature << endl;
    cout << "It is too hot" << endl;
  }
  cout << "Continue ..." << endl;
  return 0;
}
```

