#include <iostream>

// Callee: Detects invalid argument and delegates handling via throw
int quotient(int dividend, int divisor)
{
    if (divisor == 0)
    {
        throw dividend; // Throwing the dividend payload upon zero-division
    }
    return dividend / divisor;
}

int main()
{
    int a = 0, b = 0;
    if (std::cin >> a >> b)
    {
        try
        {
            int result = quotient(a, b);
            std::cout << a << " / " << b << " is " << result << "\n";
        }
        catch (int ex)
        {
            std::cout << "Exception from function: an integer " << ex
                      << " cannot be divided by zero\n";
        }
        std::cout << "Execution continues ...\n";
    }
    return 0;
}

#include <iostream>
#include <stdexcept>

// Safe division throwing standard runtime_error
int safeDivide(int dividend, int divisor)
{
    if (divisor == 0)
    {
        throw std::runtime_error("Divisor cannot be zero");
    }
    return dividend / divisor;
}

int main()
{
    int n1 = 0, n2 = 0;
    if (std::cin >> n1 >> n2)
    {
        try
        {
            int result = safeDivide(n1, n2);
            std::cout << n1 << " / " << n2 << " is " << result << "\n";
        }
        catch (const std::runtime_error& ex)
        {
            std::cout << ex.what() << "\n";
        }
        std::cout << "Execution continues ...\n";
    }
    return 0;
}
